window.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.until = async (fn, ms = 15000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (fn()) return true; await sleep(150) } return false };
window.nav = async (name) => { const b = [...document.querySelectorAll('nav button')].find((x) => x.textContent.trim() === name); if (!b) return 'NO NAV ' + name; b.click(); await sleep(2000); return 'nav ' + name };
window.setInput = (input, value) => { const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set; set.call(input, value); input.dispatchEvent(new Event('input', { bubbles: true })); input.dispatchEvent(new Event('change', { bubbles: true })) };
window.chooseSelect = async (title, value) => { const el = [...document.querySelectorAll('select')].find((x) => x.title === title); if (!el) return 'NO SELECT ' + title; Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set.call(el, String(value)); el.dispatchEvent(new Event('change', { bubbles: true })); await sleep(1500); return title + ' = ' + (el.selectedOptions[0]?.textContent ?? el.value) };
window.cells = (r) => [...r.querySelectorAll('[role=cell],td')].map((c) => c.textContent.trim());
window.rows = (n) => [...document.querySelectorAll('tbody tr,[role=row]')].slice(0, n).map((r) => cells(r).slice(0, 6).join(' | '));
window.openPlayer = async (name) => { const input = document.querySelector('input[aria-label="Search players"]'); if (!input) return 'NO SEARCH'; setInput(input, name); await until(() => [...document.querySelectorAll('aside button')].some((x) => x.textContent.includes(name))); const b = [...document.querySelectorAll('aside button')].find((x) => x.textContent.includes(name)); if (!b) return 'NOT LISTED ' + name; b.click(); await sleep(2500); return 'opened ' + name };
window.openView = async (name) => { let b = [...document.querySelectorAll('button')].find((x) => x.textContent.includes(name)); if (!b) { const menu = document.querySelector('[title="Saved views"]'); if (!menu) return false; menu.click(); await sleep(600); b = [...document.querySelectorAll('button')].find((x) => x.textContent.includes(name)) } if (!b) return false; b.click(); await sleep(3000); return true };
window.check = (label, ok, got) => (ok ? 'OK ' : 'MISMATCH ') + label + ' got ' + JSON.stringify(got);
